mapper.select:
select a.id, a.origin_id, a.status, a.remark, a.create_by, a.create_time,
b.code ,b.`type`,b.new_local,b.dept_name, b.create_by as maker
from t_out_recheck a
left join t_out_delivery b on a.origin_id = b.id

    inner join sys_user u on u.user_name = a.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    a.del_flag = '0'
    and a.origin_id = #{originId}
    and a.status = #{status}
    and b.code like concat('%',#{code},'%')
    and b.type = #{type}


${params.dataScope}
order by  a.create_time desc
